  "check_code": "import sqlite3
from pathlib import Path

CASE_ID = "DTA-2023-00044"
SOURCE_JOURNAL_ID = "JRN-NC-2024-003446"
KEY = "IDEMPOTENCY:T009-DTA-2023-00044-RESTORE"
AMOUNT = 92765
APPROVAL_DB = "imidea_approval/state.db"
NC_DB = "yonyou_nc_ledger/state.db"


def _db(ws, rel):
    return Path(ws).parent / "system" / rel


def _one(con, sql, args=()):
    row = con.execute(sql, args).fetchone()
    return dict(row) if row else None


def _journal(ws):
    path = _db(ws, NC_DB)
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    try:
        rows = con.execute(
            "SELECT * FROM journal_header WHERE description LIKE ? ORDER BY journal_id",
            (f"%[{KEY}]",),
        ).fetchall()
        return con, rows
    except Exception:
        con.close()
        raise


def check_journal_header(ws):
    con, rows = _journal(ws)
    try:
        if len(rows) != 1:
            return {"score": 0, "detail": f"fixed idempotency marker matched {len(rows)} headers, expected 1"}
        row = dict(rows[0])
        expected = {
            "entity_id": "ORG-CN-000333",
            "period_code": "PERIOD-2023-FY",
            "journal_status": "draft",
            "approval_case_id": CASE_ID,
            "source_journal_id": SOURCE_JOURNAL_ID,
            "source_system": "IMIDEA_OA",
            "approval_instruction_status": "approved",
            "recon_scope": "statutory_only",
        }
        bad = {k: (row.get(k), v) for k, v in expected.items() if row.get(k) != v}
        if bad:
            return {"score": 0, "detail": f"header mismatch: {bad}"}
        return {"score": 1, "detail": f"unique draft {row['journal_id']} has correct references and period"}
    finally:
        con.close()


def check_journal_lines(ws):
    con, headers = _journal(ws)
    try:
        if len(headers) != 1:
            return {"score": 0, "detail": "cannot inspect lines without exactly one fixed-key header"}
        journal_id = headers[0]["journal_id"]
        rows = con.execute(
            """SELECT jl.*, am.account_name FROM journal_line jl
               JOIN account_master am ON am.account_id = jl.account_id
               WHERE jl.journal_id=? ORDER BY jl.line_no""",
            (journal_id,),
        ).fetchall()
        if len(rows) != 2:
            return {"score": 0, "detail": f"line count {len(rows)} != 2"}
        debit = [r for r in rows if r["debit_thousand_yuan"] == AMOUNT and r["credit_thousand_yuan"] == 0]
        credit = [r for r in rows if r["credit_thousand_yuan"] == AMOUNT and r["debit_thousand_yuan"] == 0]
        if len(debit) != 1 or len(credit) != 1:
            return {"score": 0, "detail": "expected one debit and one credit of 92765"}
        d, c = debit[0], credit[0]
        checks = [
            d["account_id"] == "ACC-NC-181101" and d["account_name"] == "递延所得税资产",
            c["account_id"] == "ACC-NC-680102" and c["account_name"] == "所得税费用-递延所得税",
            all(r["line_status"] == "draft" for r in rows),
            all(r["tax_item_ref"] == CASE_ID for r in rows),
            all(r["source_item_id"] in {"PST-2024-003446", "AURA-WP-DT-2023-044"} for r in rows),
            len({r["source_item_id"] for r in rows}) == 1,
            sum(r["debit_thousand_yuan"] for r in rows) == sum(r["credit_thousand_yuan"] for r in rows) == AMOUNT,
        ]
        if not all(checks):
            return {"score": 0, "detail": "line accounts, references, statuses, or balance are incorrect"}
        return {"score": 1, "detail": "two draft lines use the required accounts and balance at 92765"}
    finally:
        con.close()


def check_historical_rows_untouched(ws):
    ap = sqlite3.connect(_db(ws, APPROVAL_DB))
    ap.row_factory = sqlite3.Row
    nc = sqlite3.connect(_db(ws, NC_DB))
    nc.row_factory = sqlite3.Row
    try:
        old = _one(ap, "SELECT * FROM posting_instruction WHERE instruction_id='PST-2024-003446-OLD'")
        valid = _one(ap, "SELECT * FROM posting_instruction WHERE instruction_id='PST-2024-003446'")
        if not old or old["instruction_status"] != "cancelled" or old["journal_id"] is not None or old["approved_amount_thousand_yuan"] != AMOUNT:
            return {"score": 0, "detail": "cancelled historical instruction was changed"}
        if not valid or valid["instruction_status"] != "acknowledged" or valid["journal_id"] != SOURCE_JOURNAL_ID or valid["approved_amount_thousand_yuan"] != AMOUNT:
            return {"score": 0, "detail": "acknowledged historical instruction was changed"}
        original = nc.execute("SELECT COUNT(*) FROM journal_header WHERE journal_id=?", (SOURCE_JOURNAL_ID,)).fetchone()[0]
        if original != 0:
            return {"score": 0, "detail": "source journal that should have been missing was altered or pre-existing"}
        return {"score": 1, "detail": "historical approval instructions remain unchanged and source journal remains absent"}
    finally:
        ap.close()
        nc.close()
